import os
import csv
import json

from pyscipopt import Model, quicksum

DATA_DIR = "/app/data"
SUB_DIR = "/app/submissions"

# ---------------------------------------------------------------- read data
with open(os.path.join(DATA_DIR, "config.json")) as f:
    cfg = json.load(f)
TOL = cfg.get("feasibility_tolerance", 1e-5)
SHELF = cfg.get("shelf_life_days", 5)

hospitals = {}
hosp_order = []
with open(os.path.join(DATA_DIR, "hospitals.csv")) as f:
    for row in csv.DictReader(f):
        h = row["hospital_id"]
        hospitals[h] = {
            "cap": float(row["storage_capacity_units"]),
            "order_cost": float(row["order_cost_per_unit"]),
            "short_pen": float(row["shortage_penalty_per_unit"]),
            "hold_cost": float(row["holding_cost_per_unit_day"]),
            "reserve": float(row["minimum_reserve_units"]),
        }
        hosp_order.append(h)

days = []
with open(os.path.join(DATA_DIR, "days.csv")) as f:
    for row in csv.DictReader(f):
        days.append({
            "day": row["day"],
            "idx": int(row["day_index"]),
            "cap": float(row["supplier_capacity_units"]),
            "waste_pen": float(row["waste_penalty_per_unit"]),
        })
days.sort(key=lambda r: r["idx"])
day_names = [d["day"] for d in days]

demand = {}
min_service = {}
with open(os.path.join(DATA_DIR, "demand.csv")) as f:
    for row in csv.DictReader(f):
        key = (row["hospital_id"], int(row["day"]))
        demand[key] = float(row["forecast_demand_units"])
        min_service[key] = float(row["minimum_service_rate"])

init_inv = {}
with open(os.path.join(DATA_DIR, "initial_inventory.csv")) as f:
    for row in csv.DictReader(f):
        init_inv[(row["hospital_id"], int(row["age"]))] = float(row["initial_units"])

H = hosp_order
D = list(range(len(days)))
AGES = list(range(1, SHELF + 1))  # 1..5

# ------------------------------------------------------------- build model
time_limit = 300.0
env_limit = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
if env_limit is not None:
    try:
        time_limit = min(time_limit, float(env_limit))
    except ValueError:
        pass

model = Model("platelet_inventory_rotation")
model.setParam("gaprel", 0.0005)
model.setParam("limits/time", time_limit)

o = {}   # (h, d) order
t = {}   # (h, d, a) transfuse
e = {}   # (h, d, a) ending, a in 1..4
v = {}   # (h, d) waste
s = {}   # (h, d) shortage

for h in H:
    for d in D:
        o[(h, d)] = model.addVar(name=f"o_{h}_{d}", vtype="C", lb=0.0, ub=1e6, obj=0.0)
        for a in AGES:
            t[(h, d, a)] = model.addVar(name=f"t_{h}_{d}_{a}", vtype="C", lb=0.0, ub=1e6, obj=0.0)
        for a in range(1, 5):
            e[(h, d, a)] = model.addVar(name=f"e_{h}_{d}_{a}", vtype="C", lb=0.0, ub=1e6, obj=0.0)
        v[(h, d)] = model.addVar(name=f"v_{h}_{d}", vtype="C", lb=0.0, ub=1e6, obj=0.0)
        s[(h, d)] = model.addVar(name=f"s_{h}_{d}", vtype="C", lb=0.0, ub=1e6, obj=0.0)

# objective coefficients
obj_coeff = {}
for h in H:
    for d in D:
        obj_coeff[("o", h, d)] = hospitals[h]["order_cost"]
        obj_coeff[("s", h, d)] = hospitals[h]["short_pen"]
        for a in range(1, 5):
            obj_coeff[("e", h, d, a)] = hospitals[h]["hold_cost"]
        obj_coeff[("v", h, d)] = days[d]["waste_pen"]

obj_expr = quicksum([
    obj_coeff[("o", h, d)] * o[(h, d)] for h in H for d in D
] + [
    obj_coeff[("s", h, d)] * s[(h, d)] for h in H for d in D
] + [
    obj_coeff[("e", h, d, a)] * e[(h, d, a)] for h in H for d in D for a in range(1, 5)
] + [
    obj_coeff[("v", h, d)] * v[(h, d)] for h in H for d in D
])
model.setObjective(obj_expr, sense="minimize")

# balance constraints
for h in H:
    for d in D:
        for a in AGES:
            if d == 0:
                avail = init_inv.get((h, a), 0.0)
            else:
                if a == 1:
                    avail = 0.0  # fresh orders only
                else:
                    avail = None  # carried from previous day
            if a == 1:
                # available = order + (prev ending age1 if d>0 else initial age1)
                lhs = t[(h, d, 1)] + e[(h, d, 1)]
                rhs = o[(h, d)] + (init_inv.get((h, 1), 0.0) if d == 0 else e[(h, d - 1, 1)])
                model.addCons(lhs == rhs, name=f"bal_{h}_{d}_{a}")
            elif a < 5:
                prev = init_inv.get((h, a), 0.0) if d == 0 else e[(h, d - 1, a - 1)]
                model.addCons(t[(h, d, a)] + e[(h, d, a)] == prev, name=f"bal_{h}_{d}_{a}")
            else:  # a == 5
                prev = init_inv.get((h, 5), 0.0) if d == 0 else e[(h, d - 1, 4)]
                model.addCons(t[(h, d, 5)] + v[(h, d)] == prev, name=f"bal_{h}_{d}_{a}")

def demand_key(h, d):
    return (h, day_names[d])

# service constraints
for h in H:
    for d in D:
        Dm = demand[demand_key(h, d)]
        msr = min_service[demand_key(h, d)]
        model.addCons(quicksum([t[(h, d, a)] for a in AGES]) + s[(h, d)] == Dm,
                      name=f"svc_{h}_{d}")
        model.addCons(s[(h, d)] <= (1.0 - msr) * Dm, name=f"svcfloor_{h}_{d}")

# storage capacity and reserve on ending inventory
for h in H:
    for d in D:
        endsum = quicksum([e[(h, d, a)] for a in range(1, 5)])
        model.addCons(endsum <= hospitals[h]["cap"], name=f"cap_{h}_{d}")
        model.addCons(endsum >= hospitals[h]["reserve"], name=f"res_{h}_{d}")

# supplier capacity
for d in D:
    model.addCons(quicksum([o[(h, d)] for h in H]) <= days[d]["cap"], name=f"sup_{d}")

# ------------------------------------------------------------------ solve
try:
    model.optimize()
except Exception as ex:
    print(f"Solver exception: {ex}")

status = model.getStatus()
print(f"Status: {status}")
nsols = model.getNSols()
print(f"NSols: {nsols}")

sol = model.getBestSol()
objval = None
if sol is not None and model.getNSols() > 0:
    try:
        objval = model.getObjVal()
    except Exception:
        objval = None
print(f"Objective: {objval}")

# ------------------------------------------------------- extract solution
rows = []
if sol is not None:
    for h in H:
        for d in D:
            day = day_names[d]
            ov = model.getVal(o[(h, d)])
            if ov > TOL:
                rows.append(("order", day, h, "", ov))
            sv = model.getVal(s[(h, d)])
            if sv > TOL:
                rows.append(("shortage", day, h, "", sv))
            for a in AGES:
                tv = model.getVal(t[(h, d, a)])
                if tv > TOL:
                    rows.append(("transfuse", day, h, str(a), tv))
            for a in range(1, 5):
                ev = model.getVal(e[(h, d, a)])
                if ev > TOL:
                    rows.append(("ending", day, h, str(a), ev))
            vv = model.getVal(v[(h, d)])
            if vv > TOL:
                rows.append(("waste", day, h, "5", vv))

# ---------------------------------------------------------------- validate
def getval(var):
    return model.getVal(var) if sol is not None else 0.0

viol = 0.0
for h in H:
    for d in D:
        Dm = demand[demand_key(h, d)]
        msr = min_service[demand_key(h, d)]
        # service
        svc = sum(getval(t[(h, d, a)]) for a in AGES) + getval(s[(h, d)])
        viol = max(viol, abs(svc - Dm))
        sv = getval(s[(h, d)])
        viol = max(viol, max(0.0, sv - (1.0 - msr) * Dm - TOL))
        # storage / reserve
        endsum = sum(getval(e[(h, d, a)]) for a in range(1, 5))
        viol = max(viol, max(0.0, endsum - hospitals[h]["cap"] - TOL))
        viol = max(viol, max(0.0, hospitals[h]["reserve"] - endsum - TOL))
        # balances
        for a in AGES:
            if d == 0:
                prev = init_inv.get((h, a), 0.0)
            else:
                prev = getval(e[(h, d - 1, a - 1)]) if a > 1 else 0.0
            if a == 1:
                avail = getval(o[(h, d)]) + (init_inv.get((h, 1), 0.0) if d == 0 else getval(e[(h, d - 1, 1)]))
                used = getval(t[(h, d, 1)]) + getval(e[(h, d, 1)])
            elif a < 5:
                avail = prev
                used = getval(t[(h, d, a)]) + getval(e[(h, d, a)])
            else:
                avail = prev
                used = getval(t[(h, d, 5)]) + getval(v[(h, d)])
            viol = max(viol, abs(avail - used))
for d in D:
    sup = sum(getval(o[(h, d)]) for h in H)
    viol = max(viol, max(0.0, sup - days[d]["cap"] - TOL))
print(f"Max validation violation: {viol}")

# ------------------------------------------------------------- write output
def fmt(x):
    r = round(x, 8)
    if abs(r - round(r)) < 1e-9:
        return str(int(round(r)))
    return f"{r:.8f}".rstrip("0").rstrip(".")

os.makedirs(SUB_DIR, exist_ok=True)
sol_path = os.path.join(SUB_DIR, "solution.csv")
with open(sol_path, "w", newline="") as f:
    w = csv.writer(f)
    w.writerow(["row_type", "day", "hospital_id", "age", "value"])
    for rt, day, h, age, val in rows:
        w.writerow([rt, day, h, age, fmt(val)])
print(f"Wrote {len(rows)} rows to {sol_path}")

try:
    model.free()
except Exception:
    pass
